// جستجوی محصولات بر اساس عبارت (فارسی/انگلیسی، نرم‌شده)
export function searchProducts(query) {
  const q = normalize(query);
  if (!q) return { exactUy: PRODUCTS.slice(0, 8), kind: "suggested" };
  const scored = PRODUCTS.map((p) => ({ p, score: score(p, q) }))
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score);
  if (scored.length > 0 && scored[0].score >= 60) {
    return { exact: scored[0].p, similar: scored.slice(1, 4).map((x) => x.p), kind: "product" };
  }
  if (scored.length > 0) {
    return { exact: null, suggestions: scored.slice(0, 8).map((x) => x.p), kind: "suggestions" };
  }
  return { exact: null, suggestions: PRODUCTS.slice(0, 8), kind: "empty" };
}

function normalize(s = "") {
  return s
    .toLowerCase()
    .replace(/[أإآ]/g, "ا")
    .replace(/[ي]/g, "ی")
    .replace(/[ك]/g, "ک")
    .replace(/[ء‌]/g, " ")
    .replace(/[^\w\sآ-یa-z0-9]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function score(p, q) {
  const nameN = normalize(p.name);
  const kws = p.keywords.map(normalize);
  let s = 0;
  if (kws.some((k) => q.includes(k) || k.includes(q))) s = Math.max(s, 100);
  if (nameN.includes(q)) s = Math.max(s, 80);
  const qParts = q.split(" ");
  let hits = 0;
  for (const part of qParts) {
    if (kws.some((k) => k.includes(part)) || nameN.includes(part)) hits++;
  }
  s = Math.max(s, Math.round((hits / qParts.length) * 70));
  return s;
}
